<template>
  <view class="app-stage">
    <!-- #ifdef H5 -->
    <aside class="desktop-guide"><view class="guide-brand"><Icon name="leaf" :size="30"/><text>禾序商贸</text></view><text class="guide-caption">品质连接美好生活</text><text class="guide-kicker">DESIGN TO EXPERIENCE</text><text class="guide-title">{{screen.title}}</text><text class="guide-description">{{pageId}} · 画布 {{String(screen.board).padStart(2,'0')}} / 32</text><view class="guide-actions"><button @tap="navigate('catalog')">查看全部 128 个页面 <Icon name="grid" :size="18"/></button><button @tap="navigate(management?'M02':'G01')">{{management?'切换商城端':'切换管理端'}} <Icon name="arrow" :size="18"/></button></view><view class="guide-pager"><button :disabled="index===0" @tap="navigate(catalog[index-1].id)">← 上一页</button><button :disabled="index===127" @tap="navigate(catalog[index+1].id)">下一页 →</button></view><text class="preview-note">{{backend.ready?'数据库联调 · 按商城隔离':'正在连接业务服务'}}<br/>支付渠道接入准备中</text></aside>
    <!-- #endif -->
    <view :class="['mobile-app',{management, 'home-screen':screen.layout==='home', 'login-screen':screen.layout==='login'}]" :data-page-id="pageId">
      <view class="status-bar"><text>9:41</text><view class="status-icons"><text>▮▮▮</text><text>◒</text><view class="battery"/></view></view>
      <view v-if="screen.layout!=='login'&&screen.layout!=='home'" class="page-header"><button class="icon-button" aria-label="返回" @tap="back"><Icon name="back"/></button><text>{{screen.title}}</text><button class="icon-button" aria-label="页面目录" @tap="navigate('catalog')"><Icon name="grid" :size="19"/></button></view>
      <view v-if="screen.layout==='home'" class="store-header"><view class="spread"><view class="store-brand" @tap="screen.dealer&&navigate('M42')">禾序商贸 <text v-if="!screen.dealer" class="brand-badge">公司直营</text><text v-else class="dealer-name">| 安吉优选⌄</text></view><view class="header-actions"><button class="icon-button" aria-label="购物车" @tap="navigate('M11')"><Icon name="cart"/></button><button class="icon-button" aria-label="客服" @tap="navigate('M29')"><Icon name="headset"/></button></view></view><text class="muted tiny">{{screen.dealer?'◉ 浙江省 安吉县':'正品好货 · 品质生活'}}</text><view class="search-bar" @tap="navigate('M04')"><Icon name="search" :size="17"/><text class="muted">{{screen.dealer?'搜索本店商品':'搜索商品、品牌、生活好物'}}</text></view></view>
      <view :class="['screen-content',{'with-footer':!!screen.footer||specialFooter,'with-nav':screen.nav&&!specialFooter, 'flush':screen.layout==='login'||screen.layout==='category'}]">
        <template v-if="screen.layout==='login'">
          <view class="login-landscape"><Photo asset="loginScene"/><view v-if="false" class="login-brand"><Icon name="leaf" color="white" :size="54"/><view><text>禾序商贸</text><text class="small">品质连接美好生活</text></view></view><text v-if="false" class="login-tagline">微信登录，开启品质好物之旅</text></view>
          <view class="login-panel"><view class="login-avatar"><Photo asset="avatar" :radius="60"/></view><text class="login-title">你好，微信用户</text><text class="muted">授权后即可快速登录</text><button class="primary full" :open-type="form.phoneConsent?'getPhoneNumber':undefined" @getphonenumber="form.phoneAuthCode=$event.detail.code;handle('login')" @tap="handle('login')">一键登录（微信授权）</button><view class="divider-label">或</view><button class="plain" @tap="phoneLogin=!phoneLogin">使用手机号登录</button><view v-if="phoneLogin" class="phone-login"><input v-model="form.phone" type="number" placeholder="请输入手机号"/><input v-model="form.code" placeholder="请输入短信验证码"/></view><view class="consent-box"><view class="consent" @tap="form.phoneConsent=!form.phoneConsent"><view :class="['checkbox',{checked:form.phoneConsent}]">{{form.phoneConsent?'✓':''}}</view><text>同意使用手机号</text></view><text class="muted tiny consent-hint">为方便下单、发货与售后，我们将使用您的手机号</text><view class="consent" @tap="form.consent=!form.consent"><view :class="['checkbox',{checked:form.consent}]">{{form.consent?'✓':''}}</view><text class="tiny">我已阅读并同意 <text class="green" @tap.stop="handle('policy')">《用户协议》《隐私政策》</text></text></view></view><button class="secondary full" @tap="navigate('M02')">进入浏览</button><text class="muted tiny">不同意授权也可浏览商城，暂不登录</text></view>
        </template>
        <template v-else-if="screen.layout==='home'">
          <view class="home-banner" @tap="navigate('M56')"><Photo :asset="screen.dealer?'tea':'hero'"/><view class="banner-gradient"/><view class="banner-copy"><text>{{screen.dealer?'安吉好物\n品质生活在身边':'自然之选\n让生活更美好'}}</text><text class="small">{{screen.dealer?'精选日用百货 · 服务本地家庭':'精选家居好物'}}</text><button :class="screen.dealer?'red-pill':'cream-pill'">{{screen.dealer?'领券下单':'立即选购'}}</button></view><view class="banner-dots">● ○ ○</view></view>
          <view class="home-categories"><button v-for="(item,i) in homeCategories" :key="item[0]" @tap="navigate(item[2])"><view :class="['category-icon','category-icon-'+i]"><Icon :name="item[1]" :size="27"/></view><text>{{item[0]}}</text></button></view>
          <view class="section-heading"><view><text class="section-title">{{screen.dealer?'为你推荐':'精选推荐'}}</text><text v-if="!screen.dealer" class="muted tiny">品质好物 · 生活更进一步</text></view><text class="muted tiny" @tap="navigate('M04')">更多 ›</text></view><view v-if="screen.dealer" class="sort-bar"><text class="green">综合</text><text @tap="sort='sales'">销量</text><text @tap="sort=sort==='asc'?'desc':'asc'">价格 ↕</text></view>
          <view class="products home-products"><view v-for="p in homeProducts" :key="p.id" class="product-card" @tap="selectProduct(p.id)"><view class="goods-photo"><Photo :asset="p.asset"/></view><view class="goods-info"><text class="product-name">{{p.name}}</text><text class="small">{{p.desc}}</text><view class="product-tags"><text>品质好物</text><text>精选推荐</text></view><view class="spread"><text class="price">¥{{money(p.price)}}</text><button class="add-round" aria-label="加入购物车" @tap.stop="cartAdd(p.id)"><Icon name="cart" :size="19" color="white"/></button></view></view></view></view>
        </template>
        <template v-else-if="screen.layout==='category'">
          <view class="category-search search-bar"><Icon name="search" :size="16"/><input v-model="search" placeholder="搜索商品"/><button class="search-button" @tap="searchApplied=search">搜索</button></view><view class="category-layout"><view class="category-sidebar"><button v-for="item in categories" :key="item" :class="{active:category===item}" @tap="category=item">{{item}}</button></view><view class="category-results"><view class="sort-bar"><button :class="{green:sort==='default'}" @tap="sort='default'">综合</button><button @tap="sort='sales'">销量</button><button @tap="sort=sort==='asc'?'desc':'asc'">价格 ↕</button></view><view v-for="p in categoryProducts" :key="p.id" class="category-product" @tap="selectProduct(p.id)"><view class="category-photo"><Photo :asset="p.asset"/></view><view class="flex-one"><text class="product-name">{{p.name}}</text><text class="product-tag">{{p.spec||p.desc}}</text><text class="price">¥{{money(p.price)}}</text><view class="spread"><text class="tiny muted">月销 {{p.sales||0}}</text><button class="add-round" @tap.stop="cartAdd(p.id)"><Icon name="cart" color="white" :size="17"/></button></view></view></view><text v-if="!categoryProducts.length" class="empty-text">暂无相关商品，试试其他分类</text><text class="end-line">没有更多商品了</text></view></view>
        </template>
        <template v-else-if="screen.layout==='product'||screen.layout==='sku'">
          <view class="detail-photo"><Photo :asset="currentProduct.id==='stapler'&&currentProduct.asset==='stapler'?'product':currentProduct.asset" :radius="0"/><text class="photo-count">1 / {{currentProduct.gallery?.length||1}}</text></view><view class="card detail-info"><view class="spread"><view><text v-if="screen.agent" class="badge">云代理专享价</text><text class="detail-price">¥{{money(screen.agent?(currentProduct.agent||currentProduct.price):currentProduct.price)}}</text><text v-if="screen.agent" class="muted tiny">零售价 ¥{{money(currentProduct.price)}}</text></view><button class="icon-button" aria-label="分享商品" @tap="handle('share')"><Icon name="share"/></button></view><text class="detail-name">{{currentProduct.name}}</text><text class="muted small">{{currentProduct.desc}}</text><view class="spread muted tiny"><text>快递：结算时核算</text><text>月销{{currentProduct.sales||0}}</text><text>库存{{currentProduct.stock}}件</text></view></view><view class="card"><view class="info-row" @tap="navigate('M07')"><text class="muted">已选</text><text class="flex-one">{{form.spec||currentProduct.spec}} × {{qty}}</text><Icon name="chevron" :size="16"/></view><view class="info-row"><text class="muted">配送</text><text>{{address.region||'请选择收货地址'}}</text></view><view class="service-strip"><text>✓ 正品保障</text><text>✓ 售后无忧</text><text>✓ 安全支付</text></view></view>
          <view v-if="screen.layout==='sku'" class="card sku-panel"><text class="section-title">颜色分类</text><view class="chips"><button v-for="v in productVariants" :key="v.id" :class="{selected:currentProduct.id===v.id}" @tap="state.selectedProduct=v.id;form.spec=v.spec;qty=1;persist()">{{v.spec||v.name}}</button></view><view class="info-row"><text class="flex-one">购买数量</text><view class="stepper"><button @tap="qty=Math.max(1,qty-1)">−</button><text>{{qty}}</text><button @tap="qty=Math.min(currentProduct.stock,qty+1)">+</button></view></view><text class="muted tiny">库存 {{currentProduct.stock}} 件</text></view><template v-else><view class="card"><view class="spread" @tap="navigate('M09')"><text class="section-title">商品评价（{{backend.reviews.length}}）</text><text class="green small">{{backend.reviews.length?Math.round(backend.reviews.filter(r=>r.rating>=4).length/backend.reviews.length*100)+'%好评':'暂无评价'}} ›</text></view><text class="small">{{backend.reviews[0]?.name||'暂无评价'}} <text class="gold">{{'★'.repeat(Number(backend.reviews[0]?.rating)||0)}}</text></text><text class="review-text">{{backend.reviews[0]?.content||'期待您的真实购买评价'}}</text></view><text class="section-title centered">商品详情</text><view class="product-detail-poster"><Photo :asset="currentProduct.asset"/><text>{{currentProduct.description||'品质之选 · 每一处都用心'}}</text></view></template>
        </template>
        <template v-else-if="screen.layout==='cart'">
          <view class="spread cart-title"><text>共 {{state.cart.length}} 件商品</text><button class="plain" @tap="editingCart=!editingCart">{{editingCart?'完成':'管理'}}</button></view><view class="card"><view class="shop-heading"><Icon name="shop" :size="20"/><text class="bold">{{state.shop}}</text></view><view v-for="line in state.cart" :key="line.id" class="cart-line"><view :class="['checkbox',{checked:line.selected}]" @tap="line.selected=!line.selected;persist()">{{line.selected?'✓':''}}</view><view class="product-thumb" @tap="selectProduct(line.id)"><Photo :asset="findProduct(line.id).asset"/></view><view class="product-copy"><text class="product-name">{{findProduct(line.id).name}}</text><text class="muted tiny">{{findProduct(line.id).spec}}</text><view class="spread"><text class="price">¥{{money(findProduct(line.id).price)}}</text><view class="stepper"><button @tap="changeQty(line,-1)">−</button><text>{{line.qty}}</text><button @tap="changeQty(line,1)">+</button></view></view></view><button v-if="editingCart" class="icon-button" aria-label="删除商品" @tap="deleteCart(line)"><Icon name="trash" :size="18"/></button></view></view><view v-if="!state.cart.length" class="empty-state"><Icon name="cart" :size="50"/><text>购物车还是空的</text><button class="primary" @tap="navigate('M02')">去逛逛</button></view><UiBlock :block="{type:'notice',title:'温馨提示',body:'库存和价格以下单确认时为准，优惠在结算页计算。'}" :form="form"/>
        </template>
        <template v-else-if="screen.layout==='checkout'">
          <view class="card address-choice" @tap="navigate('M13')"><Icon name="pin" :size="25"/><view class="flex-one"><text class="bold">{{address.name}} {{address.phone}}</text><text class="small muted">{{address.region}} {{address.detail}}</text></view><Icon name="chevron" :size="18"/></view><view class="card"><view class="shop-heading"><Icon name="shop"/><text class="bold">{{state.shop}}</text></view><view v-for="line in selectedLines" :key="line.id" class="product-line inner"><view class="product-thumb"><Photo :asset="findProduct(line.id).asset"/></view><view class="product-copy"><text class="product-name">{{findProduct(line.id).name}}</text><text class="tiny muted">{{findProduct(line.id).spec}} × {{line.qty}}</text><text class="price">¥{{money(findProduct(line.id).price)}}</text></view></view><view class="info-row"><text class="row-label">配送方式</text><text class="row-value">{{!checkoutQuote?(quoteError?'运费核算未完成':'正在核算运费'):freight?'普通快递 · ¥'+money(freight):'普通快递 · 包邮'}}</text></view><view class="info-row" @tap="!state.buyNow?.groupId&&!state.buyNow?.groupCampaignId&&navigate('M61')"><text class="row-label">优惠券</text><text class="row-value red">{{state.buyNow?.groupId||state.buyNow?.groupCampaignId?'拼团价不叠加优惠券':discount?'−¥'+money(discount):'选择优惠券'}}</text><Icon name="chevron" :size="14"/></view><view class="info-row"><text class="row-label">积分抵扣（可用{{state.points}}）</text><switch :checked="!!form.usePoints&&!state.buyNow?.groupId&&!state.buyNow?.groupCampaignId" :disabled="!!state.buyNow?.groupId||!!state.buyNow?.groupCampaignId" color="#155641" @change="form.usePoints=$event.detail.value"/></view><view class="field"><text>买家留言</text><input v-model="form.remark" placeholder="选填，与商家协商一致"/></view></view><UiBlock :block="{type:'rows',title:'费用明细',items:[{label:'商品金额',value:'¥'+money(total)},{label:state.buyNow?.groupId||state.buyNow?.groupCampaignId?'拼团优惠':'优惠券',value:'−¥'+money(discount)},{label:'积分抵扣',value:'−¥'+money(pointsDiscount)},{label:'运费',value:'¥'+money(freight)},{label:'实付款',value:'¥'+money(payTotal)}]}" :form="form"/><view class="consent" @tap="form.orderConsent=!form.orderConsent"><view :class="['checkbox',{checked:form.orderConsent}]">{{form.orderConsent?'✓':''}}</view><text class="tiny muted">已确认商品、地址和金额，并同意购买协议</text></view>
        </template>
        <template v-else-if="screen.layout==='addresses'"><view v-for="(a,i) in state.addresses" :key="i" class="card address-card"><view class="spread" @tap="selectAddress(i)"><text class="bold">{{a.name}} <text class="muted">{{a.phone}}</text></text><text v-if="a.primary" class="badge">默认</text></view><text class="address-detail" @tap="selectAddress(i)">{{a.region}} {{a.detail}}</text><view class="spread address-actions"><button class="plain" @tap="setDefault(i)"><view :class="['radio',{checked:a.primary}]">{{a.primary?'✓':''}}</view>设为默认</button><view class="inline-actions"><button class="plain" @tap="editAddress(i)"><Icon name="edit" :size="16"/>编辑</button><button class="plain" @tap="removeAddress(i)"><Icon name="trash" :size="16"/>删除</button></view></view></view></template>
        <template v-else-if="screen.layout==='orders'"><UiBlock :block="{type:'tabs',items:['全部','待付款','待发货','待收货','已完成']}" :form="form" @filter="filter=$event"/><view v-for="o in []" :key="o.id" class="card" @tap="state.activeOrder=o.id;persist();navigate('M18')"><view class="spread"><text class="small">{{o.id}}</text><text class="green">{{o.status}}</text></view><text class="order-total">{{o.items.length}}款商品 · 合计 ¥{{money(o.total)}}</text><button class="mini-btn" @tap.stop="state.activeOrder=o.id;persist();navigate(o.status==='待付款'?'M15':'M18')">{{o.status==='待付款'?'去付款':'查看订单'}}</button></view><UiBlock :block="{type:'orderList'}" :form="form" :filter="filter" @action="handle"/></template>
        <template v-else-if="screen.layout==='profile'"><view class="profile-hero"><view class="profile-card" @tap="navigate('M26')"><view class="avatar"><Photo asset="avatar" :radius="50"/></view><view><text class="profile-name">{{backend.member?.name||'微信用户'}}</text><text class="small">{{backend.member?.phone?.replace(/(\d{3})\d{4}(\d{4})/,'$1****$2')||'手机号待授权'}} · 悦享品质生活</text></view><Icon name="chevron" color="white" :size="18"/></view><view class="profile-metrics"><view @tap="navigate('M50')"><text>{{state.points}}</text><text>我的积分</text></view><view @tap="navigate('M55')"><text>{{backend.coupons.filter(c=>c.kind==='coupon_claim'&&c.status==='AVAILABLE').length}}</text><text>优惠券</text></view><view @tap="navigate('M08')"><text>{{state.favorites.length}}</text><text>我的收藏</text></view></view></view><view class="card"><view class="spread" @tap="navigate('M17')"><text class="section-title">我的订单</text><text class="muted small">全部订单 ›</text></view><UiBlock :block="{type:'links',items:[{title:'待付款',icon:'wallet',target:'M17'},{title:'待发货',icon:'bag',target:'M17'},{title:'待收货',icon:'truck',target:'M19'},{title:'售后',icon:'refresh',target:'M20'}]}" :form="form" @action="handle"/></view><view class="agent-invite" @tap="navigate('M33')"><Icon name="team" :size="30"/><view><text class="bold">代理中心</text><text class="tiny">携手禾序 · 共享成长</text></view><text>立即进入 →</text></view><UiBlock :block="{type:'links',items:profileLinks}" :form="form" @action="handle"/><UiBlock :block="{type:'rows',items:[{label:'隐私授权与协议',target:'M27'},{label:'账号注销',target:'M28'}]}" :form="form" @action="handle"/></template>
        <template v-else-if="screen.layout==='withdrawal'"><view class="card"><text class="muted">提现到</text><view class="info-row" @tap="navigate('M48')"><Icon name="wallet"/><text class="flex-one bold">{{withdrawAccountLabel}}</text><Icon name="chevron" :size="16"/></view></view><view class="card withdraw-card"><text class="section-title">提现金额</text><view class="money-input"><text>¥</text><input v-model="form.amount" type="digit" placeholder="0.00" aria-label="提现金额"/></view><view class="spread small"><text class="muted">可提现余额 ¥{{money(state.balance)}}</text><text class="green" @tap="form.amount=money(state.balance)">全部提现</text></view></view><UiBlock :block="{type:'rows',title:'费用明细',items:[{label:'手续费（0.6%）',value:'¥'+money(withdrawQuote.fee||0)},{label:'预计到账',value:'¥'+money(withdrawQuote.net||0)}]}" :form="form"/><UiBlock :block="{type:'notice',title:'提现说明',body:'单次最低1元，手续费0.6%。商城拥有者审核后提交渠道，以实际付款结果为准。',tone:'orange'}" :form="form"/><view class="consent" @tap="form.consent=!form.consent"><view :class="['checkbox',{checked:form.consent}]">{{form.consent?'✓':''}}</view><text>我已阅读并同意《提现服务协议》</text></view></template>
        <template v-else-if="screen.layout==='transfer'"><UiBlock :block="{type:'options',key:'pointsType',items:['平台积分','商城积分']}" :form="form" @update="update"/><view class="card"><text class="section-title">接收人信息</text><view class="field"><text>手机号</text><input v-model="form.recipient" type="number" placeholder="请输入接收人手机号" aria-label="接收人手机号"/></view><view class="field"><text>接收商城</text><picker :range="receiverShops" @change="form.recipientShop=receiverShops[$event.detail.value]"><text>{{form.recipientShop||state.shop}} ›</text></picker></view></view><view class="card"><text class="section-title">转赠积分</text><input class="points-input" v-model="form.amount" type="number" placeholder="请输入转赠数量" aria-label="转赠积分"/><text class="small muted">可用{{form.pointsType==='商城积分'?state.shopPoints:state.points}}积分 · 单笔最多{{pointTransferLimit}}</text></view><UiBlock :block="{type:'notice',title:'转赠须知',body:'平台积分可跨商城转赠；商城积分仅限本商城用户。确认后不可撤回。'}" :form="form"/></template>
        <template v-if="screen.layout==='favorites'"><UiBlock :block="{type:'productGrid',ids:state.favorites}" :form="form" @action="handle"/></template>
        <UiBlock v-for="(block,i) in displayBlocks" :key="pageId+'-'+i+(block.type==='upload'&&pageId==='G46'?(backend.reconciliationLine||''): '')" :block="block" :form="form" :filter="filter" :search="search" @update="update" @action="handle" @filter="filter=$event" @search="search=$event"/>
        <view v-if="state.changes[pageId]?.result" class="notice mint"><Icon name="check"/><text>{{state.changes[pageId].result}}</text></view>
        <view v-if="management" class="data-scope">{{pageId==='G01'?'平台管理':state.shop}} · 数据权限已隔离</view>
      </view>
      <view v-if="screen.layout==='product'||screen.layout==='sku'" class="bottom-bar product-bottom"><button class="bottom-icon" @tap="navigate('M29')"><Icon name="headset"/><text>客服</text></button><button class="bottom-icon" @tap="toggleFavorite"><Icon name="heart"/><text>{{state.favorites.includes(currentProduct.id)?'已收藏':'收藏'}}</text></button><button class="secondary" @tap="cartAdd(currentProduct.id,qty)">加入购物车</button><button class="primary" @tap="buy">立即购买</button></view>
      <view v-else-if="screen.layout==='cart'" class="bottom-bar cart-bottom"><view class="consent" @tap="toggleAll"><view :class="['checkbox',{checked:allSelected}]">{{allSelected?'✓':''}}</view><text>全选</text></view><view class="flex-one right small">合计 <text class="price">¥{{money(total)}}</text><text class="tiny muted">不含运费</text></view><button class="primary" :disabled="!selectedLines.length" @tap="navigate('M12')">去结算({{selectedLines.length}})</button></view>
      <view v-else-if="screen.layout==='checkout'" class="bottom-bar"><view class="flex-one">合计 <text class="price">¥{{money(payTotal)}}</text></view><button class="primary" :disabled="!selectedLines.length" @tap="handle('checkout')">提交订单</button></view>
      <view v-else-if="screen.layout==='withdrawal'||screen.layout==='transfer'" class="bottom-bar"><button class="primary full" @tap="handle(screen.layout==='withdrawal'?'withdraw':'transfer')">{{screen.layout==='withdrawal'?'确认提现':'下一步，核对信息'}}</button></view>
