const footerItems=computed(()=>{if(backend.pageLoading[pageId])return [{label:'正在读取业务数据',disabled:true}];if(pageId==='G41')return [{label:'由平台发布分红版本',disabled:true}];if(pageId==='G55')return [{label:'核算营销金额',target:'calculate'}];if(pageId==='G39')return [{label:'刷新结算结果',target:'settle'}];if(pageId==='G42')return [{label:'核对冲正记录',target:'reverse'}];if(pageId==='G44')return [{label:'刷新付款记录',target:'query-payment'}];if(pageId==='G43'&&backend.managementWithdrawal?.status!=='PENDING')return [{label:'查看付款记录',target:'G44'}];if(['G31','G33','G35'].includes(pageId)){const list=backend.management[pageId]||[],d=list.find(x=>x.id===backend.selectedDocuments?.[pageId])||list.find(x=>x.status==='PENDING')||list[0];if(!d||!['PENDING','SUPPLEMENT'].includes(d.status))return [{label:'暂无待审核申请',disabled:true}];if(pageId==='G33'&&d.body.targetShopId!==d.shop_id)return [{label:'跨商城迁移待平台审核',disabled:true}];}if(pageId==='G11')return [{label:'待平台审核',target:'',disabled:true}];if(pageId==='G34')return [{label:'团队迁移由平台复核',disabled:true}];if(pageId==='M59'){const d=backend.linkCampaign||{};if(d.participant)return [{label:'查看我的活动',target:'M60'}];return [{label:!d.enabled?'活动尚未开启':d.canJoin?'确认参与活动':'申请代理后参与',target:d.canJoin?'link-join':'M30',disabled:!d.enabled}];}if(pageId==='G46'){const list=backend.management.G46||[],line=list.find(r=>r.id===backend.reconciliationLine)||list.find(r=>!['MATCHED','RESOLVED'].includes(r.status))||list[0];if(!line||['MATCHED','RESOLVED','PENDING'].includes(line.status))return [{label:'返回资金账本',target:'G45'}];return [{label:form.adjustment==='申请账务调整'?'提交复核':'重新核对回执',target:'submit'}];}if(pageId==='G38'){const d=(backend.management.G38||[]).find(d=>d.id===backend.selectedDowngrade)||(backend.management.G38||[]).find(d=>['PENDING','REVIEW_REQUIRED'].includes(d.status));return d&&['PENDING','REVIEW_REQUIRED'].includes(d.status)?[{label:'驳回',target:'reject',tone:'outline'},{label:'审核降级',target:'approve'}]:[{label:'核算已结束周期',target:'assessment-run'}];}if(pageId==='M58'){const g=backend.groupDetail,c=backend.groupCampaign;if(g?.myOrderId)return [{label:'查看我的订单',target:'group-order'},...(g.status==='FORMING'?[{label:'邀请好友参团',target:'group-share'}]:[])];return [{label:g?'立即参团 ¥'+money(g.price):c?'发起拼团 ¥'+money(c.price):'暂无可参与活动',target:'join-group',disabled:!g&&!c||g&&g.status!=='FORMING'}]}if(pageId==='M57'&&!backend.invitation?.canInvite)return [{label:'申请代理后参与邀请',target:'M30'}];if(['G26','G27','G28'].includes(pageId)&&backend.refund?.status!==({G26:'PENDING',G27:'WAIT_RETURN',G28:'WAIT_EXCHANGE'}[pageId]))return [{label:'返回售后列表',target:'G25'}];if(['M23','M24'].includes(pageId)){const r=backend.refund;if(!r)return [];if(r.status==='WAIT_RETURN')return [{label:'填写退货运单',target:'M22'}];if(r.status==='EXCHANGE_SHIPPED')return [{label:'确认换货收货',target:'exchange-receive'}];return [{label:'返回订单详情',target:'M18'}]}if(pageId==='M19')return [{label:backend.activeOrder?.rawStatus==='SHIPPED'?'确认收货':'返回订单',target:backend.activeOrder?.rawStatus==='SHIPPED'?'receive':'M18'}];if(pageId==='M28')return [{label:backend.closure?.eligible?'申请注销账户':'完成处理后可申请注销',target:'close-account',disabled:!backend.closure?.eligible}];if(pageId==='M18'){const o=backend.activeOrder;if(o?.group&&o.group.status!=='FORMED'&&o.rawStatus!=='UNPAID')return [{label:'查看拼团进度',target:'group-progress'}];const item={UNPAID:['继续支付','M15'],PAID:['提醒发货','remind'],SHIPPED:['确认收货','receive'],COMPLETED:['评价订单','M10'],REFUNDED:['查看售后','M23'],CANCELLED:['继续购物','M03']}[o?.rawStatus];return [{label:item?.[0]||'请先选择订单',target:item?.[1],disabled:!item}]}return Array.isArray(screen.footer)?screen.footer:[screen.footer]})
const findProduct=id=>products.find(x=>x.id===id)||{id,asset:'stapler',name:'商品暂不可售',price:0,stock:0,spec:'',desc:''}
