watch(()=>JSON.stringify([backend.ready,backend.shopId,selectedLines.value,total.value,state.points,form.usePoints,state.couponId,address.value]),async()=>{
 if(pageId!=='M12'||!backend.ready||!selectedLines.value.length)return;const version=++quoteVersion;checkoutQuote.value=null;quoteError.value='';
 try{const body={shopId:backend.shopId,address:address.value,items:selectedLines.value.map(l=>({id:l.id,qty:l.qty})),couponId:state.couponId||'',groupId:state.buyNow?.groupId,groupCampaignId:state.buyNow?.groupCampaignId,points:0};let quote=await request('/hexu/app/quote',body,'POST');if(form.usePoints&&!state.buyNow?.groupId&&!state.buyNow?.groupCampaignId){body.points=Math.min(state.points,Math.floor(Math.floor((quote.subtotal-quote.discount)*quote.deductionPercent/100)*quote.pointsPerYuan/100));if(body.points>0)quote=await request('/hexu/app/quote',body,'POST')}if(version===quoteVersion)checkoutQuote.value=quote}catch(e){if(version===quoteVersion){quoteError.value=e.message;toast(e.message)}}
},{immediate:true})
const allSelected=computed(()=>state.cart.length>0&&state.cart.every(x=>x.selected))
const receiverShops=computed(()=>form.pointsType==='商城积分'?[state.shop]:backend.shops.map(s=>s.name))
