watch(()=>form.pointsType,()=>{if(form.pointsType==='商城积分')form.recipientShop=state.shop})
const withdrawAccountLabel=computed(()=>{const a=backend.documents.settlement_account?.find(d=>d.status==='APPROVED')?.body;return a?(a.masked||[a.bankName,a.bank].filter(Boolean).join(' ')):'请先添加并审核结算账户'})
