const homeCategories=computed(()=>screen.dealer?[['领券中心','coupon','M55'],['新品上架','leaf','M04'],['热销推荐','star','M56'],['生活家居','home','M04'],['个人护理','bag','M04']]:[['居家生活','home','M04'],['美食饮品','gift','M04'],['个护清洁','leaf','M04'],['数码家电','grid','M04'],['运动户外','bag','M04']])
