const isNavActive=id=>pageId===id||id==='M02'&&pageId==='M03'||id==='G01'&&['G02','G03'].includes(pageId)
const displayBlocks=computed(()=>{const blocks=JSON.parse(JSON.stringify(screen.blocks));if(pageId==='M15'&&activeOrder.value){blocks.find(x=>x.type==='amount').value=money(activeOrder.value.total);blocks.filter(x=>x.type==='rows')[0].items[0].value=activeOrder.value.id;blocks.filter(x=>x.type==='rows')[0].items[1].value='¥'+money(activeOrder.value.total)}if(pageId==='M16'&&activeOrder.value){blocks[0].value='¥'+money(activeOrder.value.total);blocks[1].items[0].value=activeOrder.value.id}if(pageId==='M18'&&activeOrder.value){const o=activeOrder.value;blocks[0].title=o.status;blocks[1].items[0].value=o.id;blocks[2]={type:'product',...o.items[0],price:money(o.items[0]?.unitPrice||0)};blocks[3].items=[{label:'商品总价',value:'¥'+money(o.subtotal)},{label:'优惠金额',value:'−¥'+money(o.subtotal+o.freight-o.total)},{label:'运费',value:'¥'+money(o.freight)},{label:'实付款',value:'¥'+money(o.total)}]}if(pageId==='M50')blocks[0].items[0].value=state.points.toLocaleString();if(pageId==='M52'&&state.pendingTransfer){const t=state.pendingTransfer;blocks[0].subtitle=t.phone;blocks[1].items[0].value=t.type;blocks[1].items[1].value=t.amount;blocks[1].items[2].value=t.before;blocks[1].items[3].value=t.before-t.amount}if(pageId==='M49'&&state.lastWithdrawal){const w=state.lastWithdrawal;blocks[0]={type:'success',title:'申请已提交',value:'¥'+money(w.net),body:'等待商城拥有者审核，实际到账以渠道结果为准'};blocks[1].active=0;blocks[2].items[0].value='¥'+money(w.cents);blocks[2].items[1].value='¥'+money(w.fee);blocks[2].items[2].value='¥'+money(w.net)}if(pageId==='M62'){blocks[2].items[0].value=state.points;blocks[2].items[1].value=Math.max(0,state.points-2800*Number(form.兑换数量||1))}if(pageId==='M63'&&state.lastRedemption){blocks[2].items[0].value=state.lastRedemption.cost;blocks[2].items[1].value=state.points}return liveBlocks(pageId,blocks,form,filter.value)})
let reportTimer,reportPolling=false
function stopReportPolling(){clearInterval(reportTimer)}
onShow(async()=>{if(pageId==='M11')state.buyNow=null;await pageData(pageId,form);stopReportPolling();if(['G58','G59'].includes(pageId))reportTimer=setInterval(async()=>{if(reportPolling||!['QUEUED','RUNNING'].includes(backend.reports?.[pageId]?.status))return;reportPolling=true;try{await refreshMobileReport(pageId,filter.value)}catch(e){stopReportPolling();toast(e.message)}finally{reportPolling=false}},2000)})
onHide(stopReportPolling);onBeforeUnmount(stopReportPolling)
