function back(){const pages=getCurrentPages();if(pages.length>1)uni.navigateBack();else navigate(management?'G01':'M02')}
function selectProduct(id){state.selectedProduct=id;persist();navigate('M05')}
async function cartAdd(id,count=1){if(addCart(id,count)){try{await syncCart();toast('已加入购物车')}catch(e){toast(e.message)}}else toast('库存不足，无法添加')}
