function changeQty(line,d){const n=line.qty+d;if(n<1)return;if(n>findProduct(line.id).stock)return toast('已超过可售库存');line.qty=n;persist();syncCart().catch(e=>toast(e.message))}
function deleteCart(line){state.cart=state.cart.filter(x=>x!==line);persist();syncCart().catch(e=>toast(e.message))}
