function selectAddress(i){state.selectedAddress=i;persist();navigate(state.wholesaleCheckout?'G15':'M12')}
async function setDefault(i){try{const a=state.addresses[i];await apiCommand('document-save',{...a,kind:'address',id:a.serverId,primary:true,consent:true});await refresh()}catch(e){toast(e.message)}}
function editAddress(i){state.editAddress=i;persist();navigate('M14')}
function removeAddress(i){uni.showModal({title:'删除地址',content:'确认删除这个收货地址？',success:async r=>{if(r.confirm){try{await apiCommand('document-remove',{id:state.addresses[i].serverId});state.selectedAddress=0;await refresh()}catch(e){toast(e.message)}}}})}
function validate(){for(const b of screen.blocks)if(b.type==='fields')for(const f of b.items)if(f.required&&!String(form[f.key]??'').trim()){toast('请填写'+f.label);return false}if(form.phone&&!validPhone(form.phone)){toast('请输入正确的手机号码');return false}return true}
function saved(message='已保存'){state.changes[pageId]={...form,result:message};persist();toast(message)}
async function handle(target){
 if(pageId==='M38'&&target==='M39')target='promotion-apply';
 if(pageId==='G19'&&target==='G20')target='stocktake-propose';
 if(target==='after-type'){state.afterType=form.afterType;backend.afterDraft=JSON.parse(JSON.stringify(form));}
 if(await handleRemote(target,{pageId,form,activeFilter:filter.value,selectedLines:selectedLines.value,payTotal:payTotal.value,pointsDiscount:pointsUsed.value,checkoutQuote:checkoutQuote.value,quoteError:quoteError.value,address:address.value,validate}))return;

 if(!target)return;
 if(/^[MG]\d{2}$/.test(target)){if(target==='M14')state.editAddress=null;navigate(target);return}
 if(target.startsWith('switch-shop:')){state.shop=target.split(':')[1];persist();navigate('M03');return}
 if(target==='policy'){uni.showModal({title:'用户协议与隐私政策',content:'您的资料与业务记录将用于账户、订单、履约及售后服务。完整用户协议、隐私政策和第三方共享清单尚待经营主体配置，正式发布前需完成审核。',showCancel:false});return}
 if(target==='login'){if(!form.consent||!form.phoneConsent)return toast('请阅读协议并勾选授权选项');if(phoneLogin.value)return toast('短信登录渠道尚未配置，请使用微信授权');state.signedIn=true;persist();navigate('M02');return}
 if(target==='checkout'){if(!state.addresses.length)return toast('请先添加收货地址');if(!form.orderConsent)return toast('请确认购买协议');if(!selectedLines.value.length)return toast('请选择商品');if(selectedLines.value.some(l=>l.qty>findProduct(l.id).stock))return toast('部分商品库存不足');const order={id:'HX'+Date.now(),items:JSON.parse(JSON.stringify(selectedLines.value)),subtotal:total.value,total:payTotal.value,points:pointsDiscount.value,status:'待付款',address:{...address.value}};state.orders.unshift(order);state.activeOrder=order.id;persist();navigate('M15');return}
 if(target==='payment'){uni.showModal({title:'演示支付',content:'当前为界面演示，不会扣款。确认后将模拟支付成功并更新本机订单。',success:r=>{if(r.confirm){const o=activeOrder.value;if(o&&o.status==='待付款'){if(o.points>state.points)return toast('积分余额已变动，请返回重新结算');o.status='待发货';state.points-=o.points;state.cart=state.cart.filter(x=>!o.items.some(l=>l.id===x.id));state.buyNow=null;notify('订单'+o.id+'模拟支付成功')}navigate('M16')}}});return}
 if(target==='save-address'){if(!validate())return;if(!form.addressConsent)return toast('请授权使用地址信息');const a={name:form.name,phone:form.phone,region:form.region,detail:form.detail,primary:form.primary};if(a.primary)state.addresses.forEach(x=>x.primary=false);if(state.editAddress!==null&&state.editAddress!==undefined)state.addresses[state.editAddress]=a;else state.addresses.push(a);state.editAddress=null;persist();navigate('M13');return}
 if(target==='withdraw'){if(withdrawQuote.value.error)return toast(withdrawQuote.value.error);if(!form.consent)return toast('请阅读并同意提现协议');state.lastWithdrawal={...withdrawQuote.value,status:'待审核',id:'TX'+Date.now()};state.balance-=withdrawQuote.value.cents;notify('提现申请已提交，等待商城拥有者审核');navigate('M49');return}
 if(target==='transfer'){if(!validPhone(form.recipient))return toast('请输入正确接收人手机号');if(form.recipient===backend.member?.phone)return toast('不能转赠给自己');const isShop=form.pointsType==='商城积分';const before=isShop?(state.shopPoints??860):state.points;const q=pointsTransfer(form.amount,before,isShop?'shop':'platform',true,pointTransferLimit.value);if(q.error)return toast(q.error);state.pendingTransfer={...q,before,phone:form.recipient,type:isShop?'商城积分':'平台积分'};persist();navigate('M52');return}
 if(target==='confirm-transfer'){const t=state.pendingTransfer;if(!t)return toast('请先填写转赠信息');const balance=t.type==='商城积分'?(state.shopPoints??860):state.points;const q=pointsTransfer(t.amount,balance);if(q.error)return toast(q.error);if(t.type==='商城积分')state.shopPoints=q.balance;else state.points=q.balance;state.transfers=state.transfers||[];state.transfers.unshift({id:'JF'+Date.now(),debit:-t.amount,credit:t.amount,phone:t.phone});state.pendingTransfer=null;notify('已转赠'+t.amount+'积分，双边流水已记录');navigate('M53');return}
 if(target==='checkin'){if(state.signedToday)return toast('今天已经签到过了');state.points+=5;state.signedToday=true;persist();toast('签到成功，获得5积分');return}
 if(target==='redeem'){const cost=2800*Number(form.兑换数量||1);if(state.points<cost)return toast('积分不足，暂时无法兑换');if(!state.addresses.length)return toast('请先添加收货地址');state.points-=cost;state.lastRedemption={cost,id:'DH'+Date.now()};notify('积分兑换成功，等待发货');navigate('M63');return}
 if(target==='choose-coupon'){state.couponId=form.coupon;persist();navigate('M12');return}
 if(target==='wholesale'){if(Number(form.boxes)<2)return toast('2箱起批，每箱24件');state.purchaseBoxes=Number(form.boxes);persist();navigate('G15');return}
 if(target==='purchase'){state.purchase={boxes:state.purchaseBoxes||2,direct:form.delivery==='整箱直发',received:false};notify('采购订单已提交（演示）');navigate('G16');return}
 if(target==='stock-receive'){if(state.purchase?.received)return toast('该采购单已收货，请勿重复入库');const p=state.purchase||{boxes:2,direct:false};p.received=true;state.purchase=p;state.stockAdded=(state.stockAdded||0)+(p.direct?0:p.boxes*24);saved(p.direct?'直发订单已确认收货，不增加商城库存':'已确认收货，库存增加'+p.boxes*24+'件');return}
 if(target==='enable-link'){if(form.enabled&&(!form.writtenConfirmed||!form.uploads?.length))return toast('启用前请上传并确认书面材料');saved(form.enabled?'启用设置已保存（演示）':'联动2加1保持关闭');return}
 if(target==='share'){uni.setClipboardData({data:'https://hexu.example/invite/C?shop=anxi',success:()=>toast('演示邀请链接已复制')});return}
 if(target==='export'){toast('请先生成真实业务报表');return}
 if(target==='help'){uni.showModal({title:'提现说明',content:'审核拒绝会说明原因并返还冻结金额。渠道付款失败确认后解冻余额，可核对账户后重新申请。审核通过并不代表到账。',showCancel:false});return}
 if(['backup','restore','authorize','upload-cert','query-payment'].includes(target)){uni.showModal({title:'服务尚未连接',content:'此操作需要接入真实服务端及相应权限。当前已保留界面和操作入口，未执行外部操作。',showCancel:false});return}
 if(target==='calculate'){if(Number(form.rate)<0||Number(form.rate)>100)return toast('分红比例应在0至100之间');toast('试算已更新');return}
 if(target==='remind'){notify('已记录提醒发货请求');toast('已提醒商家发货');return}
 if(target==='receive'){if(activeOrder.value)activeOrder.value.status='已完成';notify('已确认收货');navigate('M10');return}
 if(target==='after-type'){navigate('M21');return}
 
 if(target==='bind'){if(!form.consent)return toast('请阅读并同意授权协议');if(!state.boundAgent)state.boundAgent='C 云代理';persist();toast('已绑定'+state.boundAgent+'，首次归属保持不变');navigate('M03');return}
 if(!validate())return;
 if(target==='agent-apply'&&!form.consent)return toast('请同意代理合作协议');
 if(target==='refund'&&(Number(form.退款金额)<=0||Number(form.退款金额)>80.10))return toast('退款金额需在0.01至80.10元之间');
 if(target==='ship'&&!/^[A-Za-z0-9]{8,30}$/.test(form.tracking))return toast('请输入8至30位有效运单号');
 if(target==='reject'&&!String(form.opinion||form.审核意见||'').trim())return toast('请填写驳回原因');
 if(target==='decorate'){state.shop=form.商城名称||state.shop;persist()}
 const routes={'agent-apply':'M31','agent-resubmit':'M31','store-apply':'M31','migration':'M41','refund':'M23','return-tracking':'M23','ship':'G24','review':'M09'};
 const labels={approve:'审核通过（演示记录）',reject:'已驳回（演示记录）',supplement:'已记录补充资料要求',submit:'申请已提交（演示）',publish:'配置已保存（演示）',message:'留言已提交（演示）',settle:'结算批次已生成（演示）',reverse:'冲正已记录（演示）','cancel-after':'售后申请已撤销（演示）'};
 if(target==='approve'&&pageId==='G43'){saved(labels.approve);navigate('G44');return}
 if(target==='review'){state.points+=10;persist()}
 saved(labels[target]||'已保存');if(routes[target])navigate(routes[target]);
}
</script>

